<script setup>
import {request} from '../session'
import {action} from '../data'
import ResourcePage from '../components/ResourcePage.vue'
const fields=[{key:'name',label:'name',required:true},{key:'provider',label:'provider',required:true,options:[{value:'http',label:'HTTP Bridge'},{value:'mock',label:'mockTestOnly'}]},{key:'gateway_url',label:'gatewayUrl',wide:true,placeholder:'https://voice-provider.example.com'},{key:'credential_ref',label:'credentialRef',hint:'credentialRefHint',placeholder:'PRIMARY_PBX'},{key:'caller_id',label:'callerId'},{key:'max_concurrency',label:'concurrency',type:'number',min:1,max:10000},{key:'priority',label:'linePriority',type:'number',min:1,max:10000},{key:'weight',label:'lineWeight',type:'number',min:1,max:100},{key:'enabled',label:'enabled',type:'boolean'}]
